     3→import { ChatMessage, ToolCallInfo } from '../models/chat.models';
     4→import { A2UISurface } from '../models/a2ui.models';
     5→
     6→/**
     7→ * ChatStateService
     8→ *
     9→ * Manages conversation messages, streaming status, and session identity.
    10→ * All state is managed through Angular signals for reactive updates.
    11→ */
    12→@Injectable({
    13→  providedIn: 'root',
    14→})
    15→export class ChatStateService {
    16→  // Core signals
    17→  readonly messages = signal<ChatMessage[]>([]);
    18→  readonly isStreaming = signal<boolean>(false);
    19→  readonly currentStreamingMessage = signal<ChatMessage | null>(null);
    20→  readonly error = signal<string | null>(null);
    21→
    22→  // Computed signals
    23→  readonly lastVisualization = computed(() => {
    24→    const msgs = this.messages();
    25→    // Find the most recent message with an A2UI payload
    26→    for (let i = msgs.length - 1; i >= 0; i--) {
    27→      if (msgs[i].a2uiPayload !== null) {
    28→        return msgs[i];
    29→      }
    30→    }
    31→    return null;
    32→  });
    33→
    34→  readonly messageCount = computed(() => this.messages().length);
    35→
    36→  readonly hasActiveConversation = computed(() => this.messageCount() > 0);
    37→
    38→  /**
    39→   * Add a user message to the conversation
    40→   */
    41→  addUserMessage(content: string): void {
    42→    const message: ChatMessage = {
    43→      id: this.generateMessageId(),
    44→      role: 'user',
    45→      content: content.trim(),
    46→      timestamp: new Date(),
    47→      isStreaming: false,
    48→      a2uiPayload: null,
    49→      toolCalls: null,
    50→    };
    51→
    52→    this.messages.update((msgs) => [...msgs, message]);
    53→    this.clearError();
    54→  }
    55→
    56→  /**
    57→   * Start a new assistant message (called when TEXT_MESSAGE_START event received).
    58→   * Guards against creating a duplicate message when one is already streaming.
    59→   */
    60→  startAssistantMessage(): void {
    61→    // If there's already an active streaming message, finalize it first
    62→    if (this.currentStreamingMessage()) {
    63→      this.finalizeStreamingMessage();
    64→    }
    65→
    66→    const message: ChatMessage = {
    67→      id: this.generateMessageId(),
    68→      role: 'assistant',
    69→      content: '',
    70→      timestamp: new Date(),
    71→      isStreaming: true,
    72→      a2uiPayload: null,
    73→      toolCalls: null,
    74→    };
    75→
    76→    this.messages.update((msgs) => [...msgs, message]);
    77→    this.currentStreamingMessage.set(message);
    78→    this.isStreaming.set(true);
    79→  }
    80→
    81→  /**
    82→   * Append content delta to the current streaming message
    83→   */
    84→  appendStreamingContent(delta: string): void {
    85→    const current = this.currentStreamingMessage();
    86→    if (!current) return;
    87→
    88→    this.messages.update((msgs) =>
    89→      msgs.map((msg) =>
    90→        msg.id === current.id ? { ...msg, content: msg.content + delta } : msg
    91→      )
    92→    );
    93→  }
    94→
    95→  /**
    96→   * Finalize the current streaming message.
    97→   * Removes duplicate if an earlier assistant message has identical content.
    98→   */
    99→  finalizeStreamingMessage(): void {
   100→    const current = this.currentStreamingMessage();
   101→    if (!current) return;
   102→
   103→    // Look up the actual accumulated content (current ref may be stale)
   104→    const actualMsg = this.messages().find((m) => m.id === current.id);
   105→    const finalContent = actualMsg?.content?.trim() || '';
   106→
   107→    // Check for duplicate: does a *previous* finalized assistant message
   108→    // already have the same content?
   109→    if (finalContent) {
   110→      const isDuplicate = this.messages().some(
   111→        (m) =>
   112→          m.id !== current.id &&
   113→          m.role === 'assistant' &&
   114→          !m.isStreaming &&
   115→          m.content.trim() === finalContent
   116→      );
   117→
   118→      if (isDuplicate) {
   119→        // Remove the duplicate message instead of finalizing it
   120→        this.messages.update((msgs) =>
   121→          msgs.filter((m) => m.id !== current.id)
   122→        );
   123→        this.currentStreamingMessage.set(null);
   124→        this.isStreaming.set(false);
   125→        return;
   126→      }
   127→    }
   128→
   129→    // Remove empty assistant messages (no content and no tool calls / a2ui payload)
   130→    if (!finalContent && !actualMsg?.toolCalls?.length && !actualMsg?.a2uiPayload) {
   131→      this.messages.update((msgs) =>
   132→        msgs.filter((m) => m.id !== current.id)
   133→      );
   134→      this.currentStreamingMessage.set(null);
   135→      this.isStreaming.set(false);
   136→      return;
   137→    }
   138→
   139→    this.messages.update((msgs) =>
   140→      msgs.map((msg) =>
   141→        msg.id === current.id ? { ...msg, isStreaming: false } : msg
   142→      )
   143→    );
   144→
   145→    this.currentStreamingMessage.set(null);
   146→    this.isStreaming.set(false);
   147→  }
   148→
   149→  /**
   150→   * Add a tool call to the current streaming message
   151→   */
   152→  addToolCall(toolInfo: ToolCallInfo): void {
   153→    const current = this.currentStreamingMessage();
   154→    if (!current) return;
   155→
   156→    this.messages.update((msgs) =>
   157→      msgs.map((msg) => {
   158→        if (msg.id === current.id) {
   159→          const existingCalls = msg.toolCalls || [];
   160→          // Check if this tool call already exists (by name) and update it
   161→          const existingIndex = existingCalls.findIndex(
   162→            (call) => call.toolName === toolInfo.toolName
   163→          );
   164→
   165→          const updatedCalls =
   166→            existingIndex >= 0
   167→              ? existingCalls.map((call, idx) =>
   168→                  idx === existingIndex ? toolInfo : call
   169→                )
   170→              : [...existingCalls, toolInfo];
   171→
   172→          return { ...msg, toolCalls: updatedCalls };
   173→        }
   174→        return msg;
   175→      })
   176→    );
   177→  }
   178→
   179→  /**
   180→   * Attach an A2UI payload to the current streaming message
   181→   */
   182→  attachA2UIPayload(payload: A2UISurface): void {
   183→    const current = this.currentStreamingMessage();
   184→    if (!current) {
   185→      // If no streaming message, attach to the last assistant message
   186→      this.messages.update((msgs) => {
   187→        const lastAssistant = [...msgs]
   188→          .reverse()
   189→          .find((m) => m.role === 'assistant');
   190→        if (!lastAssistant) return msgs;
   191→
   192→        return msgs.map((msg) =>
   193→          msg.id === lastAssistant.id ? { ...msg, a2uiPayload: payload } : msg
   194→        );
   195→      });
   196→      return;
   197→    }
   198→
   199→    this.messages.update((msgs) =>
   200→      msgs.map((msg) =>
   201→        msg.id === current.id ? { ...msg, a2uiPayload: payload } : msg
   202→      )
   203→    );
   204→  }
   205→
   206→  /**
   207→   * Remove a message by ID (e.g., chart JSON messages not meant for display)
   208→   */
   209→  removeMessage(messageId: string): void {
   210→    this.messages.update((msgs) => msgs.filter((m) => m.id !== messageId));
   211→  }
   212→
   213→  /**
   214→   * Set an error message
   215→   */
   216→  setError(message: string): void {
   217→    this.error.set(message);
   218→    this.isStreaming.set(false);
   219→    this.currentStreamingMessage.set(null);
   220→  }
   221→
   222→  /**
   223→   * Clear the current error
   224→   */
   225→  clearError(): void {
   226→    this.error.set(null);
   227→  }
   228→
   229→  /**
   230→   * Clear all messages (reset conversation)
   231→   */
   232→  clearMessages(): void {
   233→    this.messages.set([]);
   234→    this.currentStreamingMessage.set(null);
   235→    this.isStreaming.set(false);
   236→    this.clearError();
   237→  }
   238→
   239→  /**
   240→   * Generate a unique message ID using the library's uuid v4
   241→   */
   242→  private generateMessageId(): string {
   243→    return randomUUID();
   244→  }
   245→}
