   109→  }
   110→
   111→  /**
   112→   * Build a typed AgentSubscriber — replaces the manual switch(event.type).
   113→   * Each callback receives typed event data and accumulated buffers from the library.
   114→   */
   115→  private buildSubscriber(): AgentSubscriber {
   116→    return {
   117→      // ── Logging (fires for every event) ────────────────────────
   118→      onEvent: ({ event }) => {
   119→        console.log('AG-UI Event:', event.type, event);
   120→      },
   121→
   122→      // ── Lifecycle ─────────────────────────────────────────────
   123→      onRunStartedEvent: () => {
   124→        this.chatState.isStreaming.set(true);
   125→      },
   126→
   127→      onRunFinishedEvent: () => {
   128→        this.chatState.isStreaming.set(false);
   129→      },
   130→
   131→      onRunErrorEvent: ({ event }) => {
   132→        // Suppress user-initiated abort — not an actual error
   133→        if (('code' in event && (event as any).code === 'abort') ||
   134→            ('message' in event && String((event as any).message).includes('aborted'))) {
   135→          return;
   136→        }
   137→        if (this.chatState.currentStreamingMessage()) {
   138→          this.chatState.finalizeStreamingMessage();
   139→        }
   140→        const errorMessage = (event as any).error ?? 'Agent error';
   141→        this.chatState.setError(typeof errorMessage === 'string' ? errorMessage : 'Agent error');
   142→        this.chatState.isStreaming.set(false);
   143→      },
   144→
   145→      onRunFailed: ({ error }) => {
   146→        this.clearStreamTimeout();
   147→        const msg = error?.message || '';
   148→        if (msg.includes('The run has already errored') || msg.includes('aborted')) {
   149→          return;
   150→        }
   151→        console.error('Agent error:', error);
   152→        this.chatState.setError(msg || 'Failed to connect to agent');
   153→        this.chatState.isStreaming.set(false);
   154→      },
   155→
   156→      onRunFinalized: () => {
   157→        this.clearStreamTimeout();
   158→        this.chatState.finalizeStreamingMessage();
   159→        this.chatState.isStreaming.set(false);
   160→      },
   161→
   162→      // ── Text message streaming ────────────────────────────────
   163→      onTextMessageStartEvent: () => {
   164→        this.chatState.startAssistantMessage();
   165→      },
   166→
   167→      onTextMessageContentEvent: ({ event }) => {
   168→        this.chatState.appendStreamingContent(event.delta);
   169→      },
   170→
   171→      onTextMessageEndEvent: ({ textMessageBuffer }) => {
   172→        // Check if the completed message is raw chart JSON (not meant for display).
   173→        const streamingMsg = this.chatState.currentStreamingMessage();
   174→        if (streamingMsg && this.isChartJsonContent(textMessageBuffer)) {
   175→          this.chatState.removeMessage(streamingMsg.id);
   176→          this.chatState.currentStreamingMessage.set(null);
   177→          this.chatState.isStreaming.set(false);
   178→        } else {
   179→          this.chatState.finalizeStreamingMessage();
   180→        }
   181→      },
   182→
   183→      // ── Tool calls ────────────────────────────────────────────
   184→      onToolCallStartEvent: ({ event }) => {
   185→        this.chatState.addToolCall({
   186→          toolName: event.toolCallName,
   187→          status: 'running',
   188→        });
   189→      },
   190→
   191→      onToolCallArgsEvent: ({ toolCallName, partialToolCallArgs }) => {
   192→        this.chatState.addToolCall({
   193→          toolName: toolCallName,
   194→          status: 'running',
   195→          arguments: partialToolCallArgs,
   196→        });
   197→      },
   198→
   199→      onToolCallEndEvent: ({ toolCallName }) => {
   200→        this.chatState.addToolCall({
   201→          toolName: toolCallName,
   202→          status: 'complete',
   203→        });
   204→      },
   205→
   206→      onToolCallResultEvent: ({ event }) => {
   207→        // Check for A2UI visualization payload in content
   208→        const content = (event as any).content;
   209→        if (!content) return;
   210→
   211→        try {
   212→          const parsed = typeof content === 'string' ? JSON.parse(content) : content;
   213→          if (parsed?.a2ui === true && parsed.surfaceId && Array.isArray(parsed.messages)) {
   214→            this.a2uiEventService.handleA2UIMessages(parsed.surfaceId, parsed.messages);
   215→          }
   216→        } catch {
   217→          // Not JSON or not A2UI payload — ignore
   218→        }
   219→      },
   220→
   221→      // ── State sync (library auto-applies patches via fast-json-patch) ──
   222→      onStateDeltaEvent: ({ agent }) => {
   223→        this.sharedState.syncFromAgent(agent.state);
   224→      },
   225→
   226→      onStateSnapshotEvent: ({ agent }) => {
   227→        this.sharedState.syncFromAgent(agent.state);
   228→      },
   229→
   230→      // ── Custom events (A2UI surface updates) ──────────────────
   231→      onCustomEvent: ({ event }) => {
   232→        if (event.name === 'a2ui_surface_update') {
   233→          const data = (event as any).data;
   234→          if (data?.surfaceId && Array.isArray(data.messages)) {
   235→            this.a2uiEventService.handleA2UIMessages(data.surfaceId, data.messages);
   236→          }
   237→        }
   238→      },
   239→    };
   240→  }
   241→
   242→  /**
   243→   * Detect if message content is raw chart JSON config (not user-facing text).
   244→   * Handles both pure JSON and content where JSON is wrapped with minor
   245→   * surrounding text or markdown fences.
   246→   */
   247→  private isChartJsonContent(content: string): boolean {
   248→    if (!content || !content.trim()) return false;
   249→
   250→    const jsonCandidate = this.extractJsonObject(content);
   251→    if (!jsonCandidate) return false;
   252→
   253→    try {
   254→      const parsed = JSON.parse(jsonCandidate);
   255→      if (!parsed || typeof parsed !== 'object') return false;
   256→
   257→      // Chart configuration: has chart_type/graphType + data keys
   258→      if (
   259→        ('chart_type' in parsed || 'graphType' in parsed) &&
   260→        ('labels' in parsed || 'datasets' in parsed || 'data' in parsed)
   261→      ) {
   262→        return true;
   263→      }
   264→
   265→      // Chart reference map: all keys match "chart-XXXX" pattern with string values
   266→      const keys = Object.keys(parsed);
   267→      if (
   268→        keys.length > 0 &&
   269→        keys.every((k) => /^chart-/.test(k) && typeof parsed[k] === 'string')
   270→      ) {
   271→        return true;
   272→      }
   273→
   274→      return false;
   275→    } catch {
   276→      return false;
   277→    }
   278→  }
   279→
   280→  /**
   281→   * Extract a JSON object string from content that may have surrounding text.
   282→   * Returns the JSON substring if found, or null.
   283→   */
   284→  private extractJsonObject(content: string): string | null {
   285→    let trimmed = content.trim();
   286→
   287→    // Pure JSON case (most common)
   288→    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
   289→      return trimmed;
   290→    }
   291→
   292→    // Strip markdown code fences: ```json ... ``` or ``` ... ```
   293→    const fenceMatch = trimmed.match(/```(?:json)?\s*(\{[\s\S]*\})\s*```/);
   294→    if (fenceMatch) {
   295→      return fenceMatch[1].trim();
   296→    }
   297→
   298→    // Find the outermost { ... } in the content
   299→    const firstBrace = trimmed.indexOf('{');
   300→    const lastBrace = trimmed.lastIndexOf('}');
   301→    if (firstBrace !== -1 && lastBrace > firstBrace) {
   302→      return trimmed.substring(firstBrace, lastBrace + 1);
   303→    }
   304→
   305→    return null;
   306→  }
   307→}
