    25→        role="tab"
    26→        [attr.aria-selected]="activeTab() === 'chat'"
    27→        aria-controls="panel-chat"
    28→        (click)="activeTab.set('chat')"
    29→        class="flex-1 px-6 py-3 text-sm font-medium transition-colors relative"
    30→        [class.text-blue-600]="activeTab() === 'chat'"
