     2→
     3→/**
     4→ * Represents a single message in the chat conversation
     5→ */
     6→export interface ChatMessage {
     7→  /** Unique identifier for the message */
     8→  id: string;
     9→
    10→  /** Role of the message sender */
    11→  role: 'user' | 'assistant';
    12→
    13→  /** Message content in markdown format */
    14→  content: string;
    15→
    16→  /** Timestamp when the message was created */
    17→  timestamp: Date;
    18→
    19→  /** Whether the message is currently being streamed */
    20→  isStreaming: boolean;
    21→
    22→  /** A2UI visualization payload if present */
    23→  a2uiPayload: A2UISurface | null;
    24→
    25→  /** Tool calls made by the agent (for transparency) */
    26→  toolCalls: ToolCallInfo[] | null;
    27→}
    28→
    29→/**
    30→ * Information about a tool call made by the agent
    31→ */
    32→export interface ToolCallInfo {
    33→  /** Name of the tool that was called */
    34→  toolName: string;
    35→
    36→  /** Current status of the tool call */
    37→  status: 'running' | 'complete' | 'error';
    38→
    39→  /** Time taken to execute the tool (in milliseconds) */
    40→  executionTimeMs?: number;
    41→
    42→  /** Arguments passed to the tool */
