     4→/**
     5→ * SplitViewComponent
     6→ *
     7→ * Responsive split-view layout supporting:
     8→ * - Desktop (>=1024px): Side-by-side with draggable divider
     9→ * - Tablet (768px-1023px): Tabbed layout
    10→ * - Mobile (<768px): Single panel with external toggle
    11→ *
    12→ * CRITICAL: Uses a SINGLE ng-content per slot (Angular only projects once).
    13→ * Responsive behavior is achieved via CSS media queries + data-attributes,
    14→ * NOT by duplicating ng-content in separate template branches.
    15→ */
    16→@Component({
    17→  selector: 'app-split-view',
    18→  standalone: true,
    19→  changeDetection: ChangeDetectionStrategy.OnPush,
    20→  imports: [CommonModule],
    21→  template: `
    22→    <!-- Tablet/Mobile tab bar (hidden on desktop) -->
    23→    <div class="lg:hidden border-b border-gray-200 flex flex-shrink-0 bg-white" role="tablist">
    24→      <button
    25→        role="tab"
    26→        [attr.aria-selected]="activeTab() === 'chat'"
    27→        aria-controls="panel-chat"
    28→        (click)="activeTab.set('chat')"
    29→        class="flex-1 px-6 py-3 text-sm font-medium transition-colors relative"
    30→        [class.text-blue-600]="activeTab() === 'chat'"
    31→        [class.text-gray-500]="activeTab() !== 'chat'">
    32→        Chat
    33→        @if (activeTab() === 'chat') {
    34→          <div class="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600"></div>
    35→        }
    36→      </button>
    37→      <button
    38→        role="tab"
    39→        [attr.aria-selected]="activeTab() === 'canvas'"
    40→        aria-controls="panel-canvas"
    41→        (click)="activeTab.set('canvas')"
    42→        class="flex-1 px-6 py-3 text-sm font-medium transition-colors relative"
    43→        [class.text-blue-600]="activeTab() === 'canvas'"
    44→        [class.text-gray-500]="activeTab() !== 'canvas'">
    45→        Canvas
    46→        @if (activeTab() === 'canvas') {
    47→          <div class="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600"></div>
    48→        }
    49→      </button>
    50→    </div>
    51→
    52→    <!-- Main content area (single ng-content per slot) -->
    53→    <div #desktopContainer class="flex-1 flex overflow-hidden">
    54→      <!-- Chat panel -->
    55→      <div
    56→        id="panel-chat"
    57→        role="tabpanel"
    58→        [attr.data-panel]="'chat'"
    59→        [attr.data-active]="activeTab() === 'chat'"
    60→        [style.width.%]="isCanvasFullscreen() ? 0 : chatWidth()"
    61→        [hidden]="isCanvasFullscreen()"
    62→        class="h-full overflow-hidden flex flex-col panel-wrapper">
    63→        <ng-content select="[slot='chat']"></ng-content>
    64→      </div>
    65→
    66→      <!-- Draggable divider (desktop only, hidden in fullscreen) -->
    67→      <div
    68→        role="separator"
    69→        aria-orientation="vertical"
    70→        aria-label="Resize panels"
    71→        (pointerdown)="onDividerPointerDown($event)"
    72→        [hidden]="isCanvasFullscreen()"
    73→        class="hidden lg:flex w-1.5 flex-shrink-0 bg-gray-200 cursor-col-resize hover:bg-blue-400 transition-colors relative z-10 items-center justify-center"
    74→        [class.bg-blue-500]="isDragging()"
    75→        style="touch-action: none;">
    76→        <div
    77→          class="flex flex-col gap-1 transition-opacity duration-150"
    78→          [class.opacity-0]="!isDragging()"
    79→          [class.opacity-100]="isDragging()">
    80→          <div class="w-0.5 h-0.5 bg-white rounded-full"></div>
    81→          <div class="w-0.5 h-0.5 bg-white rounded-full"></div>
    82→          <div class="w-0.5 h-0.5 bg-white rounded-full"></div>
    83→        </div>
    84→      </div>
    85→
    86→      <!-- Canvas panel -->
    87→      <div
    88→        id="panel-canvas"
    89→        role="tabpanel"
    90→        [attr.data-panel]="'canvas'"
    91→        [attr.data-active]="activeTab() === 'canvas'"
    92→        class="h-full overflow-hidden flex flex-col min-w-0 flex-1 panel-wrapper">
    93→        <ng-content select="[slot='canvas']"></ng-content>
    94→      </div>
    95→    </div>
    96→  `,
    97→  styles: [`
    98→    :host {
    99→      display: flex;
   100→      flex-direction: column;
   101→      height: 100%;
   102→      overflow: hidden;
   103→    }
   104→
   105→    /* Mobile & Tablet: only show the active panel, full width */
   106→    @media (max-width: 1023.98px) {
   107→      .panel-wrapper {
   108→        width: 100% !important;
