   101→   * Send message
   102→   */
   103→  protected async onSend(): Promise<void> {
   104→    const text = this.inputText().trim();
   105→    if (!text || this.isStreaming()) return;
   106→
   107→    // Clear input immediately
   108→    this.inputText.set('');
   109→    this.resetTextareaHeight();
   110→
   111→    // Add user message
   112→    this.chatState.addUserMessage(text);
   113→
   114→    // Run agent
   115→    try {
   116→      await this.agUiService.runAgent();
   117→    } catch (error) {
   118→      console.error('Failed to run agent:', error);
   119→    }
   120→  }
   121→
   122→  /**
   123→   * Cancel current stream
   124→   */
   125→  protected onCancel(): void {
   126→    this.agUiService.cancel();
   127→  }
   128→
   129→  /**
   130→   * Auto-resize textarea based on content
   131→   */
   132→  protected autoResize(): void {
   133→    if (!this.textareaRef) return;
   134→
   135→    const textarea = this.textareaRef.nativeElement;
   136→    textarea.style.height = 'auto';
   137→    textarea.style.height = `${Math.min(textarea.scrollHeight, 96)}px`; // max-h-24 = 96px
   138→  }
   139→
   140→  /**
   141→   * Reset textarea height
   142→   */
   143→  private resetTextareaHeight(): void {
   144→    if (!this.textareaRef) return;
   145→    this.textareaRef.nativeElement.style.height = 'auto';
   146→  }
   147→}
