     1→import { Pipe, PipeTransform } from '@angular/core';
     2→
     3→/**
     4→ * RelativeTimePipe
     5→ *
     6→ * Transforms a Date into a human-readable relative time string.
     7→ * Examples: "just now", "5m ago", "2h ago", "3d ago"
     8→ */
     9→@Pipe({
    10→  name: 'relativeTime',
    11→  standalone: true,
    12→})
    13→export class RelativeTimePipe implements PipeTransform {
    14→  transform(value: Date | string | number): string {
    15→    if (!value) return '';
    16→
    17→    const date = value instanceof Date ? value : new Date(value);
    18→    const now = new Date();
    19→    const diffMs = now.getTime() - date.getTime();
    20→
    21→    // Handle future dates
    22→    if (diffMs < 0) {
    23→      return 'in the future';
    24→    }
    25→
    26→    // Less than 1 minute
    27→    const diffSeconds = Math.floor(diffMs / 1000);
    28→    if (diffSeconds < 60) {
    29→      return 'just now';
    30→    }
    31→
    32→    // Less than 1 hour
    33→    const diffMinutes = Math.floor(diffSeconds / 60);
    34→    if (diffMinutes < 60) {
    35→      return `${diffMinutes}m ago`;
    36→    }
    37→
    38→    // Less than 1 day
    39→    const diffHours = Math.floor(diffMinutes / 60);
    40→    if (diffHours < 24) {
    41→      return `${diffHours}h ago`;
    42→    }
    43→
    44→    // Less than 1 week
    45→    const diffDays = Math.floor(diffHours / 24);
    46→    if (diffDays < 7) {
    47→      return `${diffDays}d ago`;
    48→    }
    49→
    50→    // More than 1 week - show date
    51→    return date.toLocaleDateString();
    52→  }
    53→}
